<main class="main"><div class="main__inner"><div class="settings-page"><header class="settings-page__header"><div><h1>Discount Type</h1><p>Define reusable percentage or fixed-value discounts.</p></div></header><section class="settings-card"><div class="settings-card__body"><form method="post" action="<?= url('/admin/settings/discount-types') ?>"><?= csrf_field() ?><div class="settings-grid"><div class="form-field"><label class="form-label">Name</label><input class="form-input" name="name" maxlength="120" required></div><div class="form-field"><label class="form-label">Mode</label><select class="form-select" name="discount_mode"><option value="percentage">Percentage</option><option value="fixed">Fixed Amount</option></select></div><div class="form-field"><label class="form-label">Value</label><input class="form-input" type="number" min="0" step="0.01" name="discount_value" required></div></div><button class="btn btn--primary">Save Discount Type</button></form></div></section><section class="settings-card"><div class="settings-card__body"><table class="data-table"><thead><tr><th>Name</th><th>Mode</th><th>Value</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($discounts as$d):?><tr><td><?= e($d['name']) ?></td><td><?= e($d['discount_mode']) ?></td><td><?= e($d['discount_value']) ?></td><td><?= e($d['status']) ?></td><td><form method="post" action="<?= url('/admin/settings/discount-types/'.$d['id'].'/status') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $d['status']==='active'?'inactive':'active' ?>"><button class="btn btn--secondary"><?= $d['status']==='active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
